backgrounds ?? []) as $background): ?><option value="<?= (int)$background['id']; ?>" data-url="<?= html_escape(base_url($background['file_path'])); ?>" data-path="<?= html_escape($background['file_path']); ?>" <?= (int)($back_design['background_id']??0)===(int)$background['id']?'selected':''; ?>><?= html_escape($background['label']); ?></option><?php endforeach; ?></select><small>Pilih dari galeri background yang sama; unggah background baru melalui panel desain depan.</small></div><div class="back-editor-field"><label>Teks sisi belakang</label><input type="text" id="back-org-label" class="form-control form-control-sm mb-2" maxlength="90" value="<?= html_escape($back_design['org_label'] ?? ''); ?>" placeholder="Nama instansi" data-back="org_label"><input type="text" id="back-card-title" class="form-control form-control-sm mb-2" maxlength="70" value="<?= html_escape($back_design['card_title'] ?? ''); ?>" placeholder="Judul sisi belakang" data-back="card_title"><textarea id="back-tagline" class="form-control form-control-sm mb-2" rows="4" maxlength="220" placeholder="Pesan / ketentuan singkat pada sisi belakang" data-back="tagline"><?= html_escape($back_design['tagline'] ?? ''); ?></textarea><input type="text" id="back-footer-label" class="form-control form-control-sm" maxlength="70" value="<?= html_escape($back_design['footer_label'] ?? ''); ?>" placeholder="Footer, misalnya alamat website" data-back="footer_label"></div><div class="back-editor-field"><label>Elemen sisi belakang</label><?php foreach (['show_brand'=>'Tampilkan identitas instansi','show_qr'=>'Tampilkan QR verifikasi','show_serial'=>'Tampilkan nomor kartu'] as $key=>$label): ?><div class="studio-toggle"><label for="back-<?= $key; ?>"><?= $label; ?></label><label class="form-check form-switch m-0"><input id="back-<?= $key; ?>" class="form-check-input" type="checkbox" <?= ! empty($back_design[$key])?'checked':''; ?> data-back="<?= $key; ?>"></label></div><?php endforeach; ?><div class="studio-object-upload"><select id="back-saved-object-asset" class="form-select form-select-sm"><option value="">Tambahkan logo/gambar dari galeri…</option><?php foreach (($object_assets ?? []) as $asset): ?><option value="<?= (int)$asset['id']; ?>" data-path="<?= html_escape($asset['file_path']); ?>" data-url="<?= html_escape(base_url($asset['file_path'])); ?>"><?= html_escape($asset['label']); ?></option><?php endforeach; ?></select><button type="button" class="btn btn-sm btn-outline-primary" id="add-back-saved-object"><i class="ti ti-photo-plus me-1"></i>Tambah objek</button></div><small>Klik elemen pada kanvas sisi belakang lalu geser atau ubah ukurannya langsung.</small></div></section><section class="back-preview-shell"><div class="studio-preview-head"><div><div class="section-kicker">Live preview · sisi belakang</div><h2>Kartu dua sisi yang konsisten</h2></div></div><div class="back-preview-canvas" id="back-preview"><?php $card_size='full'; $card_side='back'; $studio_editable=true; include APPPATH . 'views/members/_digital_card.php'; ?></div><div class="studio-guide"><i class="ti ti-hand-move"></i><div><strong>Atur elemen sisi belakang langsung.</strong><br>Geser elemen, atau seret kotak kecil di pojok kanan bawah untuk mengubah ukuran. Simpan & publikasikan untuk menerapkan kedua sisi kartu.</div></div></section></div><?= form_close(); ?>
</div></div>
<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script>
<script>
(function(){
	function drawQr(root){root.querySelectorAll('[data-card-qr]').forEach(function(el){if(!el.dataset.rendered){new QRCode(el,{text:el.dataset.cardQr,width:120,height:120,correctLevel:QRCode.CorrectLevel.M});el.dataset.rendered='1';}});}
	drawQr(document);
	// Studio interaction is initialized below.
	/* legacy preview binding replaced by the interactive canvas below */
	/* interactive handlers are registered below */
	var form=document.getElementById('card-studio-form'), card=document.querySelector('#studio-preview .member-card-v2'), layoutInput=document.getElementById('layout-json'), customInput=document.getElementById('custom-objects-json'), inspector=document.getElementById('object-inspector'), assetBase=<?= json_encode(rtrim(base_url(), '/') . '/'); ?>;
	var defaults={brand:{x:6,y:8,w:56,h:14},status:{x:77,y:9,w:17,h:9},photo:{x:6,y:29,w:17,h:37},member_label:{x:27,y:29,w:52,h:5},member_name:{x:27,y:34,w:56,h:22},member_number:{x:27,y:58,w:54,h:5},member_type:{x:27,y:64,w:38,h:5},expiry:{x:6,y:82,w:27,h:11},footer:{x:42,y:82,w:30,h:11},tagline:{x:42,y:92,w:38,h:4},qr:{x:86,y:79,w:9,h:14}},defaultCustom=[{id:'heritage_line',type:'line',text:'',color:'#F6C85F',fill:'#F6C85F',font_size:14,opacity:55,x:5,y:77,w:90,h:.45}],selected=null,drag=null;
	function decode(value,fallback){try{var out=JSON.parse(value);return out&&typeof out==='object'?out:fallback;}catch(e){return fallback;}}
		function limit(value,min,max){return Math.max(min,Math.min(max,value));}
		function percent(value){return (Math.round((parseFloat(value)||0)*10)/10).toFixed(1).replace(/\.0$/,'')+'%';}
	var layout=decode(layoutInput.value,{}),custom=decode(customInput.value,[]);
	Object.keys(defaults).forEach(function(key){if(!layout[key])layout[key]=Object.assign({},defaults[key]);});
	function isExtra(key){return key&&key.indexOf('custom:')===0;}
	function entry(key){return isExtra(key)?custom.find(function(item){return item.id===key.slice(7);}):layout[key];}
	function persist(){layoutInput.value=JSON.stringify(layout);customInput.value=JSON.stringify(custom);}
	function setBox(node,item){if(!node||!item)return;node.style.setProperty('--o-x',item.x+'%');node.style.setProperty('--o-y',item.y+'%');node.style.setProperty('--o-w',item.w+'%');node.style.setProperty('--o-h',item.h+'%');}
	function constrain(item){item.x=limit(parseFloat(item.x)||0,-40,140);item.y=limit(parseFloat(item.y)||0,-40,140);item.w=limit(parseFloat(item.w)||4,3,140);item.h=limit(parseFloat(item.h)||4,2,140);}
	function select(key){
		selected=key;
		card.querySelectorAll('[data-card-object]').forEach(function(node){node.classList.toggle('is-selected',node.dataset.cardObject===key);});
		var item=entry(key),node=card.querySelector('[data-card-object="'+key+'"]');
		if(!item){inspector.classList.remove('is-open');return;}
		inspector.classList.add('is-open');
		var extra=isExtra(key);
		document.getElementById('selected-object-name').textContent=extra?'Objek tambahan':'Elemen: '+(node?node.dataset.cardLabel:key);
		document.getElementById('delete-object').style.display=extra?'':'none';
		document.getElementById('custom-object-fields').style.display=extra&&item.type!=='image'?'':'none';
			['x','y','w','h'].forEach(function(field){document.getElementById('object-'+field).value=item[field];document.getElementById('object-'+field+'-value').textContent=percent(item[field]);});
		if(extra&&item.type!=='image'){document.getElementById('selected-object-text').value=item.text||'';document.getElementById('selected-object-color').value=item.color||'#FFFFFF';document.getElementById('selected-object-fill').value=item.fill||'#FFFFFF';document.getElementById('selected-object-size').value=item.font_size||14;}
	}
	function updateCoordinates(){
		if(!selected)return;var item=entry(selected);if(!item)return;
		['x','y','w','h'].forEach(function(field){item[field]=parseFloat(document.getElementById('object-'+field).value)||0;});
		constrain(item);setBox(card.querySelector('[data-card-object="'+selected+'"]'),item);persist();select(selected);
	}
	function appendExtra(item){
		var node=document.createElement('div');node.className='card-v2-object card-v2-custom type-'+item.type;node.dataset.cardObject='custom:'+item.id;node.dataset.cardLabel=item.type==='image'?'Gambar / logo':'Objek tambahan';
		node.style.color=item.color;node.style.opacity=(item.opacity||100)/100;
		node.style.background=(item.type==='badge'||item.type==='shape'||item.type==='line')?item.fill:'';
		if(item.type==='text')node.style.fontSize=(item.font_size||14)+'px';
		if(item.type==='image'){var image=document.createElement('img');image.src=item.image_url||assetBase+String(item.image_path||'').replace(/^\/+/, '');image.alt=item.text||'Logo kartu';node.appendChild(image);}else if(item.type!=='shape'&&item.type!=='line')node.textContent=item.text||'Teks baru';
		setBox(node,item);card.appendChild(node);return node;
	}
	function addExtra(type,asset){
		if(type==='image'&&!asset)return;
		var item={id:'obj_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),type:type,text:type==='badge'?'LABEL BARU':(asset&&asset.label?asset.label:'Teks baru'),color:'#FFFFFF',fill:type==='badge'?'#0B75BE':'#FFFFFF',font_size:14,opacity:(type==='shape'||type==='line')?35:100,x:36,y:43,w:type==='line'?28:(type==='image'?18:22),h:type==='line'?2:(type==='image'?18:8)};
		if(type==='image'){item.asset_id=parseInt(asset.id,10);item.image_path=asset.path;item.image_url=asset.url;}
		custom.push(item);var node=appendExtra(item);persist();select(node.dataset.cardObject);
	}
	function repaintExtra(){
		if(!selected||!isExtra(selected))return;var item=entry(selected),old=card.querySelector('[data-card-object="'+selected+'"]');if(old)old.remove();
		var node=appendExtra(item);persist();select(node.dataset.cardObject);
	}
	function updateVisual(){
		var fd=new FormData(form);
		card.style.setProperty('--card-primary',fd.get('primary'));card.style.setProperty('--card-secondary',fd.get('secondary'));card.style.setProperty('--card-accent',fd.get('accent'));
		card.style.setProperty('--card-radius',fd.get('corner_style')==='square'?'8px':(fd.get('corner_style')==='soft'?'34px':'23px'));
		card.classList.remove('surface-aurora','surface-grid','surface-solid');card.classList.add('surface-'+fd.get('surface'));
		var labels={org_label:'.card-v2-org',card_title:'.card-v2-title',footer_label:'.card-v2-meta .card-v2-footer-label',tagline:'.card-v2-tagline'};
		Object.keys(labels).forEach(function(key){var node=card.querySelector(labels[key]);if(node&&fd.get(key))node.textContent=fd.get(key);});
		[['show_brand','.card-v2-brand'],['show_photo','.card-v2-photo'],['show_qr','.card-v2-qr'],['show_status','.card-v2-status'],['show_expiry','[data-card-object="expiry"]']].forEach(function(pair){var node=card.querySelector(pair[1]),enabled=pair[0]==='show_brand'?document.getElementById('show_brand').checked:fd.get(pair[0]);if(node)(node.closest('[data-card-object]')||node).style.display=enabled?'':'none';});
			var memberType=card.querySelector('[data-card-object="member_type"]');if(memberType)memberType.style.display=fd.get('show_member_type')?'':'none';
			var selectedBackground=document.querySelector('.studio-background.is-selected');applyBackground(selectedBackground?selectedBackground.dataset.backgroundUrl:'');
		}
		function applyBackground(url){
			if(url){var primary=document.querySelector('[name="primary"]').value,secondary=document.querySelector('[name="secondary"]').value,safe=String(url).replace(/"/g,'%22');card.classList.add('has-custom-background');card.style.backgroundImage='linear-gradient(127deg,'+primary+'66,'+secondary+'4D),url("'+safe+'")';card.style.backgroundSize='cover';card.style.backgroundPosition='center';}
			else{card.classList.remove('has-custom-background');card.style.removeProperty('background-image');card.style.removeProperty('background-size');card.style.removeProperty('background-position');}
		}
	card.addEventListener('pointerdown',function(event){
		var node=event.target.closest('[data-card-object]');if(!node)return;event.preventDefault();
		var key=node.dataset.cardObject,item=entry(key),rect=card.getBoundingClientRect(),box=node.getBoundingClientRect();
		select(key);drag={key:key,node:node,mode:event.clientX>box.right-19&&event.clientY>box.bottom-19?'resize':'move',x:event.clientX,y:event.clientY,rect:rect,start:{x:+item.x,y:+item.y,w:+item.w,h:+item.h}};
		node.setPointerCapture(event.pointerId);
	});
	card.addEventListener('pointermove',function(event){
		if(!drag)return;var item=entry(drag.key),dx=(event.clientX-drag.x)/drag.rect.width*100,dy=(event.clientY-drag.y)/drag.rect.height*100;
		if(drag.mode==='move'){item.x=limit(drag.start.x+dx,-40,140);item.y=limit(drag.start.y+dy,-40,140);}
		else{item.w=limit(drag.start.w+dx,3,140);item.h=limit(drag.start.h+dy,2,140);}
		setBox(drag.node,item);persist();
	});
	card.addEventListener('pointerup',function(){if(!drag)return;var key=drag.key;drag=null;select(key);});
	form.addEventListener('input',updateVisual);form.addEventListener('change',function(event){updateVisual();if(event.target.name==='photo_position'){if(event.target.value==='right'){layout.photo={x:76,y:29,w:18,h:36};layout.member_label={x:7,y:29,w:60,h:5};layout.member_name={x:7,y:34,w:64,h:23};layout.member_number={x:7,y:58,w:64,h:5};layout.member_type={x:7,y:64,w:38,h:5};}else{layout.photo=Object.assign({},defaults.photo);layout.member_label=Object.assign({},defaults.member_label);layout.member_name=Object.assign({},defaults.member_name);layout.member_number=Object.assign({},defaults.member_number);layout.member_type=Object.assign({},defaults.member_type);}['photo','member_label','member_name','member_number','member_type'].forEach(function(key){setBox(card.querySelector('[data-card-object="'+key+'"]'),layout[key]);});persist();}});
		document.querySelectorAll('[data-preset]').forEach(function(button){button.addEventListener('click',function(){var colors=this.dataset.preset.split('|');['primary','secondary','accent'].forEach(function(key,index){document.querySelector('[name="'+key+'"]').value=colors[index];});updateVisual();});});
		document.querySelectorAll('[data-background-id]').forEach(function(button){button.addEventListener('click',function(){document.getElementById('background-id').value=this.dataset.backgroundId;document.querySelectorAll('[data-background-id]').forEach(function(item){item.classList.toggle('is-selected',item===button);});applyBackground(this.dataset.backgroundUrl||'');});});
		var uploadButton=document.getElementById('upload-background');if(uploadButton)uploadButton.addEventListener('click',function(){var file=document.getElementById('background-file').files[0];if(!file){alert('Pilih gambar background terlebih dahulu.');return;}var data=new FormData();data.append('background_file',file);data.append('label',document.getElementById('background-label').value);uploadButton.disabled=true;fetch(uploadButton.dataset.uploadUrl,{method:'POST',body:data,credentials:'same-origin'}).then(function(response){if(!response.ok)throw new Error('Upload background gagal.');window.location.reload();}).catch(function(error){alert(error.message||'Upload background gagal.');uploadButton.disabled=false;});});
	var savedObjectButton=document.getElementById('add-saved-object');if(savedObjectButton)savedObjectButton.addEventListener('click',function(){var selectAsset=document.getElementById('saved-object-asset'),option=selectAsset.options[selectAsset.selectedIndex];if(!option||!option.value){alert('Pilih gambar atau logo dari galeri terlebih dahulu.');return;}addExtra('image',{id:option.value,label:option.text,path:option.dataset.path,url:option.dataset.url});});
	var uploadObjectButton=document.getElementById('upload-object');if(uploadObjectButton)uploadObjectButton.addEventListener('click',function(){var file=document.getElementById('object-file').files[0];if(!file){alert('Pilih gambar atau logo terlebih dahulu.');return;}var data=new FormData();data.append('object_file',file);data.append('label',document.getElementById('object-label').value);uploadObjectButton.disabled=true;fetch(uploadObjectButton.dataset.uploadUrl,{method:'POST',body:data,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){return response.json().then(function(payload){if(!response.ok||!payload.ok)throw new Error(payload.message||'Upload objek gagal.');return payload;});}).then(function(payload){var selectAsset=document.getElementById('saved-object-asset'),option=document.createElement('option');option.value=payload.asset.id;option.dataset.path=payload.asset.path;option.dataset.url=payload.asset.url;option.textContent=payload.asset.label;selectAsset.insertBefore(option,selectAsset.options[1]||null);selectAsset.value=option.value;document.getElementById('object-file').value='';document.getElementById('object-label').value='';addExtra('image',payload.asset);}).catch(function(error){alert(error.message||'Upload objek gagal.');}).finally(function(){uploadObjectButton.disabled=false;});});
	document.querySelectorAll('[data-add-object]').forEach(function(button){button.addEventListener('click',function(){addExtra(this.dataset.addObject);});});
	['x','y','w','h'].forEach(function(key){document.getElementById('object-'+key).addEventListener('input',updateCoordinates);});
	['text','color','fill','size'].forEach(function(key){document.getElementById('selected-object-'+key).addEventListener('input',function(){if(!selected||!isExtra(selected))return;var item=entry(selected);item[key==='size'?'font_size':key]=key==='size'?parseInt(this.value,10):this.value;repaintExtra();});});
	document.getElementById('delete-object').addEventListener('click',function(){if(!selected||!isExtra(selected))return;var key=selected;custom=custom.filter(function(item){return 'custom:'+item.id!==key;});var node=card.querySelector('[data-card-object="'+key+'"]');if(node)node.remove();selected=null;persist();inspector.classList.remove('is-open');});
	var backInput=document.getElementById('back-json'),backCard=document.querySelector('#back-preview .member-card-v2'),back=decode(backInput?backInput.value:'',{}),backDrag=null;
	var backDefaults={brand:{x:6,y:8,w:56,h:14},title:{x:8,y:34,w:62,h:16},message:{x:8,y:53,w:61,h:14},serial:{x:8,y:82,w:35,h:8},footer:{x:50,y:82,w:30,h:8},qr:{x:84,y:76,w:10,h:16}};
	if(backCard){if(!back.layout)back.layout={};Object.keys(backDefaults).forEach(function(key){if(!back.layout[key])back.layout[key]=Object.assign({},backDefaults[key]);});function persistBack(){backInput.value=JSON.stringify(back);}function backBox(node,item){if(!node||!item)return;node.style.setProperty('--o-x',item.x+'%');node.style.setProperty('--o-y',item.y+'%');node.style.setProperty('--o-w',item.w+'%');node.style.setProperty('--o-h',item.h+'%');}function updateBackVisual(){var primary=back.primary||'#062D62',secondary=back.secondary||'#087D82',accent=back.accent||'#F6C85F';backCard.style.setProperty('--card-primary',primary);backCard.style.setProperty('--card-secondary',secondary);backCard.style.setProperty('--card-accent',accent);backCard.style.setProperty('--card-radius',back.corner_style==='square'?'8px':(back.corner_style==='soft'?'34px':'23px'));backCard.classList.remove('surface-aurora','surface-grid','surface-solid');backCard.classList.add('surface-'+(back.surface||'grid'));var bg=back.background_path?assetBase+String(back.background_path).replace(/^\/+/, ''):'';if(bg){backCard.classList.add('has-custom-background');backCard.style.backgroundImage='linear-gradient(127deg,'+primary+'66,'+secondary+'4D),url("'+bg.replace(/"/g,'%22')+'")';backCard.style.backgroundSize='cover';backCard.style.backgroundPosition='center';}else{backCard.classList.remove('has-custom-background');backCard.style.removeProperty('background-image');backCard.style.removeProperty('background-size');backCard.style.removeProperty('background-position');}var org=backCard.querySelector('.card-v2-org'),brandTitle=backCard.querySelector('.card-v2-brand .card-v2-title'),title=backCard.querySelector('.card-v2-back-title h2'),message=backCard.querySelector('.card-v2-back-message'),footer=backCard.querySelector('[data-card-object="footer"] .card-v2-footer-label');if(org)org.textContent=back.org_label||'';if(brandTitle)brandTitle.textContent=back.card_title||'';if(title)title.textContent=back.card_title||'';if(message)message.textContent=back.tagline||'';if(footer)footer.textContent=back.footer_label||'';[['brand','show_brand'],['qr','show_qr'],['serial','show_serial']].forEach(function(pair){var node=backCard.querySelector('[data-card-object="'+pair[0]+'"]');if(node)node.style.display=back[pair[1]]?'':'none';});Object.keys(back.layout).forEach(function(key){backBox(backCard.querySelector('[data-card-object="'+key+'"]'),back.layout[key]);});persistBack();}
		document.querySelectorAll('[data-back]').forEach(function(control){var refresh=function(){var key=control.dataset.back;if(control.type==='checkbox')back[key]=control.checked;else back[key]=control.value;if(key==='background_id'){var option=control.options[control.selectedIndex];back.background_id=parseInt(control.value,10)||0;back.background_path=option&&option.dataset.path?option.dataset.path:null;}updateBackVisual();};control.addEventListener('input',refresh);control.addEventListener('change',refresh);});
		function appendBackImage(asset){if(!back.custom_objects)back.custom_objects=[];var item={id:'obj_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),type:'image',asset_id:parseInt(asset.id,10),image_path:asset.path,image_url:asset.url,text:asset.label||'Logo kartu',color:'#FFFFFF',fill:'#FFFFFF',font_size:14,opacity:100,x:72,y:36,w:18,h:18};back.custom_objects.push(item);var node=document.createElement('div');node.className='card-v2-object card-v2-custom type-image';node.dataset.cardObject='custom:'+item.id;node.dataset.cardLabel='Gambar / logo';var image=document.createElement('img');image.src=item.image_url||assetBase+String(item.image_path||'').replace(/^\/+/, '');image.alt=item.text;node.appendChild(image);backBox(node,item);backCard.appendChild(node);persistBack();}
		var addBackObject=document.getElementById('add-back-saved-object');if(addBackObject)addBackObject.addEventListener('click',function(){var selectAsset=document.getElementById('back-saved-object-asset'),option=selectAsset.options[selectAsset.selectedIndex];if(!option||!option.value){alert('Pilih gambar atau logo dari galeri terlebih dahulu.');return;}appendBackImage({id:option.value,label:option.text,path:option.dataset.path,url:option.dataset.url});});
		backCard.addEventListener('pointerdown',function(event){var node=event.target.closest('[data-card-object]');if(!node)return;event.preventDefault();var key=node.dataset.cardObject,isCustom=key.indexOf('custom:')===0,item=isCustom?(back.custom_objects||[]).find(function(object){return object.id===key.slice(7);}):back.layout[key];if(!item)return;var rect=backCard.getBoundingClientRect(),box=node.getBoundingClientRect();backCard.querySelectorAll('[data-card-object]').forEach(function(el){el.classList.toggle('is-selected',el===node);});backDrag={node:node,key:key,isCustom:isCustom,mode:event.clientX>box.right-19&&event.clientY>box.bottom-19?'resize':'move',x:event.clientX,y:event.clientY,rect:rect,start:{x:+item.x,y:+item.y,w:+item.w,h:+item.h}};node.setPointerCapture(event.pointerId);});backCard.addEventListener('pointermove',function(event){if(!backDrag)return;var item=backDrag.isCustom?(back.custom_objects||[]).find(function(object){return object.id===backDrag.key.slice(7);}):back.layout[backDrag.key];if(!item)return;var dx=(event.clientX-backDrag.x)/backDrag.rect.width*100,dy=(event.clientY-backDrag.y)/backDrag.rect.height*100;if(backDrag.mode==='move'){item.x=limit(backDrag.start.x+dx,-40,140);item.y=limit(backDrag.start.y+dy,-40,140);}else{item.w=limit(backDrag.start.w+dx,3,140);item.h=limit(backDrag.start.h+dy,2,140);}backBox(backDrag.node,item);persistBack();});backCard.addEventListener('pointerup',function(){backDrag=null;});updateBackVisual();}
		updateVisual();persist();
})();
</script>
